import { SegmentBuffer } from "./solution";

function assert(condition: boolean, message: string): void {
    if (!condition) throw new Error(message);
}

function throws(action: () => unknown, expected: typeof TypeError | typeof RangeError, message: string): void {
    let error: unknown;
    try { action(); } catch (caught) { error = caught; }
    assert(error instanceof expected, message);
}

const buffer = new SegmentBuffer(4);
assert(buffer.length === 4, "length is exposed");
assert(buffer.serialize() === "|||", "new cells are empty and default separator is used");
buffer.setRange(1, 3, "x");
assert(buffer.get(0) === "" && buffer.get(1) === "x" && buffer.get(2) === "x" && buffer.get(3) === "", "setRange writes exactly the half-open range");
assert(buffer.serialize(",") === ",x,x,", "custom separator is used");
buffer.setRange(2, 2, "ignored");
assert(buffer.serialize() === "|x|x|", "empty range is a no-op");
buffer.setRange(0, 4, "z");
assert(buffer.serialize() === "z|z|z|z", "full boundary range is accepted");

const snap1 = buffer.snapshot();
const snap2 = buffer.snapshot();
assert(snap1 !== snap2 && snap1.cells !== snap2.cells, "snapshots contain fresh objects and arrays");
assert(snap1.length === 4 && snap1.cells.join(",") === "z,z,z,z", "snapshot contains complete state");
(snap1.cells as string[])[0] = "changed";
assert(buffer.get(0) === "z", "snapshot array cannot mutate the buffer");

const sourceCells = ["a", "b"];
const restored = SegmentBuffer.fromSnapshot({ length: 2, cells: sourceCells });
sourceCells[0] = "mutated";
assert(restored.serialize() === "a|b", "fromSnapshot copies source cells");
const restoredSnapshot = restored.snapshot();
(restoredSnapshot.cells as string[])[1] = "mutated";
assert(restored.get(1) === "b", "returned snapshot cells are isolated");
restored.setRange(0, 1, "c");
assert(sourceCells[0] === "mutated" && sourceCells[1] === "b", "buffer mutation does not affect source array");

const empty = new SegmentBuffer(0);
assert(empty.serialize() === "", "zero-length buffer serializes to empty string");
empty.setRange(0, 0, "valid");
assert(empty.snapshot().cells.length === 0, "zero-length empty range is valid");

for (const invalidLength of [-1, 1.2, NaN, Infinity, Number.MAX_SAFE_INTEGER + 1]) {
    throws(() => new SegmentBuffer(invalidLength), RangeError, "invalid length throws RangeError");
}
for (const invalidIndex of [-1, 4, 1.5, NaN, Infinity]) {
    throws(() => buffer.get(invalidIndex), RangeError, "invalid get index throws RangeError");
}
const invalidRanges: Array<[number, number]> = [[-1, 1], [0, 5], [3, 2], [0.5, 2], [0, NaN], [0, Infinity]];
for (const [start, end] of invalidRanges) {
    throws(() => buffer.setRange(start, end, "x"), RangeError, "invalid range throws RangeError");
}
throws(() => buffer.setRange(0, 1, 2 as unknown as string), TypeError, "non-string cell value throws TypeError");
throws(() => buffer.serialize(2 as unknown as string), TypeError, "non-string separator throws TypeError");

throws(() => SegmentBuffer.fromSnapshot(null as unknown as { length: number; cells: readonly string[] }), TypeError, "null snapshot is rejected");
throws(() => SegmentBuffer.fromSnapshot({ length: -1, cells: [] }), RangeError, "invalid snapshot length is rejected");
throws(() => SegmentBuffer.fromSnapshot({ length: 2, cells: ["a"] }), RangeError, "snapshot cell count must match length");
throws(() => SegmentBuffer.fromSnapshot({ length: 1, cells: [7 as unknown as string] }), TypeError, "snapshot cells must be strings");
throws(() => SegmentBuffer.fromSnapshot({ length: 1, cells: null as unknown as readonly string[] }), TypeError, "snapshot cells must be an array");

